from logging import getLogger
from urllib3 import disable_warnings, InsecureRequestWarning
from requests.exceptions import InvalidSchema, SSLError, ConnectionError, ChunkedEncodingError
from urllib.error import HTTPError, URLError
from requests import Session, Request
from json.decoder import JSONDecodeError

logger = getLogger()


class HttpClient:
    """Replaces the 'connection_handler' function with a class-based, injectable service."""

    def __init__(self, verify_ssl=True):
        self.session = Session()
        self.verify_ssl = verify_ssl
        self._disable_warnings()

    def _disable_warnings(self):
        disable_warnings(InsecureRequestWarning)

    def get_json(self, url, params=None, headers=None, as_is_reply=False):
        """Perform GET request and return JSON or raw Response."""
        try:
            self.session.params = params or {}
            if headers:
                self.session.headers.update(headers)
            request = self.session.prepare_request(Request('GET', url))
            response = self.session.send(request, verify=self.verify_ssl)
            return self._handle_response(response, as_is_reply)
        except (InvalidSchema, SSLError, ConnectionError, ChunkedEncodingError, HTTPError, URLError) as e:
            logger.error('Network request failed: %s', e)
            return None

    def post_json(self, url, json=None, headers=None, as_is_reply=False):
        """Perform POST request and return JSON or raw Response."""
        try:
            if headers:
                self.session.headers.update(headers)
            request = self.session.prepare_request(Request('POST', url, json=json))
            response = self.session.send(request, verify=self.verify_ssl)
            return self._handle_response(response, as_is_reply)
        except (InvalidSchema, SSLError, ConnectionError, ChunkedEncodingError, HTTPError, URLError) as e:
            logger.error('Network request failed: %s', e)
            return None

    def _handle_response(self, response, as_is_reply):
        """Handle response logic previously in helpers.connection_handler."""
        if response.status_code == 401:
            if 'NoSiteContext' in str(response.content):
                logger.info('Your Site is incorrect for %s', response.url)
            elif 'LoginRequired' in str(response.content):
                logger.info('Your login credentials are incorrect for %s', response.url)
            else:
                logger.info('Your API key is incorrect for %s', response.url)
        elif response.status_code == 404:
            logger.info('This url does not resolve: %s', response.url)

        if as_is_reply:
            return response

        if response.status_code == 200:
            try:
                return response.json()
            except JSONDecodeError:
                logger.error('No JSON response. Response is: %s', response.text)
        return None
